                key={skill.name}
                layout
                initial={{ opacity: 0, scale: 0.2 }}
                animate={{ 
                  opacity: 1, 
                  scale: 1,
                  y: [0, -8, 0],
                }}
                exit={{ opacity: 0, scale: 0.2 }}
                transition={{
                  opacity: { duration: 0.3 },
                  layout: { duration: 0.3 },
                  y: {
                    duration: 3 + (index % 3),
                    repeat: Infinity,
                    ease: "easeInOut",
                    delay: index * 0.1
                  }
                }}
                className={`group relative flex items-center justify-center w-28 h-28 sm:w-32 sm:h-32 rounded-full cursor-pointer bg-white shadow-[0_4px_20px_rgba(0,0,0,0.03)] border border-pastel-blue hover:shadow-[0_8px_30px_rgba(204,251,241,0.6)] hover:border-pastel-teal transition-all`}
              >
                <div className="text-center z-10 p-2">
                  <span className="block text-primary-dark font-semibold text-sm sm:text-base transition-transform group-hover:-translate-y-2">
                    {skill.name}
                  </span>

                  {/* Hover info */}
                  <div className="absolute inset-0 flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300 rounded-full bg-white/95 backdrop-blur-sm">
                    <span className="text-xs font-bold text-primary-dark mb-1">{skill.category}</span>
                    <span className={`text-[10px] font-medium px-2 py-0.5 rounded-full ${skill.color}`}>
                      {skill.proficiency}
                    </span>
                  </div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </motion.div>
      </div>
    </section>
  );
}
